import java.util.*;

public class Main {
    static int n, mod;
    static Map<Integer, Integer>[][] memo;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        mod = sc.nextInt();

        // Initialize memo array
        memo = new HashMap[n + 1][2];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < 2; j++) {
                memo[i][j] = new HashMap<>();
            }
        }

        int ans = solve(n, 0, true) % mod;
        System.out.println(ans);
        sc.close();
    }

    static int invnum(int[] seq) {
        int N = seq.length;
        int res = 0;
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                if (seq[i] > seq[j]) {
                    res++;
                }
            }
        }
        return res;
    }

    static int naive(int N, int k, boolean flag) {
        int res = 0;
        List<int[]> permutationsP = generatePermutations(N);
        List<int[]> permutationsQ = generatePermutations(N);
        for (int[] p : permutationsP) {
            for (int[] q : permutationsQ) {
                if ((comparePermutations(p, q) < 0 || !flag) && (invnum(p) - invnum(q) > k)) {
                    res++;
                }
            }
        }
        return res;
    }

    static List<int[]> generatePermutations(int N) {
        List<int[]> result = new ArrayList<>();
        permute(new int[N], new boolean[N], 0, N, result);
        return result;
    }

    static void permute(int[] arr, boolean[] used, int depth, int N, List<int[]> result) {
        if (depth == N) {
            result.add(arr.clone());
            return;
        }
        for (int i = 0; i < N; i++) {
            if (!used[i]) {
                used[i] = true;
                arr[depth] = i;
                permute(arr, used, depth + 1, N, result);
                used[i] = false;
            }
        }
    }

    static int comparePermutations(int[] p, int[] q) {
        for (int i = 0; i < p.length; i++) {
            if (p[i] != q[i]) {
                return p[i] - q[i];
            }
        }
        return 0;
    }

    static int solve(int N, int k, boolean flag) {
        int flagInt = flag ? 1 : 0;
        if (memo[N][flagInt].containsKey(k)) {
            return memo[N][flagInt].get(k);
        }

        int res;
        if (N == 1) {
            res = flag ? 0 : (k < 0 ? 1 : 0);
            memo[N][flagInt].put(k, res);
            return res;
        }

        int invnum_INF = (N * (N - 1)) / 2;

        if (k < -invnum_INF - 1) {
            res = solve(N, -invnum_INF - 1, flag);
            memo[N][flagInt].put(k, res);
            return res;
        }

        if (k >= invnum_INF) {
            res = 0;
            memo[N][flagInt].put(k, res);
            return res;
        }

        res = 0;
        for (int delta = -N + 1; delta < N; delta++) {
            if (flag && delta > 0) {
                continue;
            }
            int wt = Math.min(N - delta, delta + N);
            int newFlag = (delta == 0) && flag ? 1 : 0;
            res += (int) ((long) solve(N - 1, k - delta, newFlag == 1) * wt) % mod;
            res %= mod;
        }
        memo[N][flagInt].put(k, res % mod);
        return res % mod;
    }
}
